    if (ra == rb) return;
    if (size[ra] < size[rb]) {
      final t = ra;
      ra = rb;
      rb = t;
    }
    p[rb] = ra;
    size[ra] += size[rb];
  }

  union(0, 1);
  union(2, 0);
  print(size[find(2)]);
}
